10	#ifndef TIMG2COL_CPU_HPP
11	#define TIMG2COL_CPU_HPP
12	
13	#include <algorithm>
14	#include <cstdint>
15	#include "pto/cpu/tile_offsets.hpp"
16	
17	namespace pto {
18	namespace cpu_img2col {
19	template <typename ConvTileData>
20	inline size_t GetInputOffset(
21	    const ConvTileData& src, int64_t n, int64_t d, int64_t c1, int64_t h, int64_t w, int64_t c0)
22	{
23	    const int64_t c0Size = src.GetShape(ConvTileData::totalDimCount - 1);
24	    if constexpr (ConvTileData::layout == Layout::NC1HWC0) {
25	        const int64_t c1Size = src.GetShape(1);
26	        const int64_t hSize = src.GetShape(2);
27	        const int64_t wSize = src.GetShape(3);
28	        return static_cast<size_t>(((((n * c1Size + c1) * hSize + h) * wSize + w) * c0Size) + c0);
29	    } else {
30	        const int64_t dSize = src.GetShape(1);
31	        const int64_t c1Size = src.GetShape(2);
32	        const int64_t hSize = src.GetShape(3);
33	        const int64_t wSize = src.GetShape(4);
34	        return static_cast<size_t>((((((n * dSize + d) * c1Size + c1) * hSize + h) * wSize + w) * c0Size) + c0);
35	    }
36	}
37	
38	template <typename TileData, typename ConvTileData>
39	inline void Timg2colCheck()
40	{
41	    static_assert(ConvTileData::Loc == TileType::Mat, "TImg2col: Source TileType only support Mat.");
42	    static_assert(TileData::Loc == TileType::Left, "TImg2col: Destination TileType only support Left.");
43	    static_assert(
44	        (ConvTileData::layout == Layout::NC1HWC0) || (ConvTileData::layout == Layout::NDC1HWC0),
45	        "TImg2col: Source layout only support NC1HWC0/NDC1HWC0.");
46	    static_assert(
47	        TileData::SFractal == SLayout::RowMajor && !TileData::isRowMajor,
48	        "TImg2col: Destination layout only support SLayout RowMajor + BLayout ColMajor.");
49	    static_assert(
50	        std::is_same_v<typename ConvTileData::DType, typename TileData::DType>,
51	        "TImg2col: Destination and source tile data types must match.");
52	}
53	} // namespace cpu_img2col
54	
55	template <typename ConvTileData>
56	struct Img2ColParams {
57	    int64_t fmapN;
58	    int64_t fmapD;
59	    int64_t fmapC1;
60	    int64_t fmapH;
61	    int64_t fmapW;
62	    int64_t fmapC0;
63	    int64_t strideH;
64	    int64_t strideW;
65	    int64_t dilationH;
66	    int64_t dilationW;
67	    int64_t filterH;
68	    int64_t filterW;
69	    int64_t padLeft;
70	    int64_t padRight;
71	    int64_t padTop;
72	    int64_t padBottom;
73	    int64_t channelSize;
74	    int64_t outH;
75	    int64_t outW;
76	};
77	
78	template <typename ConvTileData>
79	PTO_INTERNAL Img2ColParams<ConvTileData> ExtractImg2ColParams(const ConvTileData& src)
80	{
81	    Img2ColParams<ConvTileData> params;
82	
83	    params.fmapN = src.GetShape(0);
84	    params.fmapD = (ConvTileData::layout == Layout::NDC1HWC0) ? src.GetShape(1) : 1;
85	    params.fmapC1 = (ConvTileData::layout == Layout::NDC1HWC0) ? src.GetShape(2) : src.GetShape(1);
86	    params.fmapH = (ConvTileData::layout == Layout::NDC1HWC0) ? src.GetShape(3) : src.GetShape(2);
87	    params.fmapW = (ConvTileData::layout == Layout::NDC1HWC0) ? src.GetShape(4) : src.GetShape(3);
88	    params.fmapC0 = src.GetShape(ConvTileData::totalDimCount - 1);
89	    params.strideH = src.GetStrideH();
90	    params.strideW = src.GetStrideW();
91	    params.dilationH = src.GetDilationH();
92	    params.dilationW = src.GetDilationW();
93	    params.filterH = src.GetFilterH();
94	    params.filterW = src.GetFilterW();
95	    params.padLeft = src.GetPadList(0);
96	    params.padRight = src.GetPadList(1);
97	    params.padTop = src.GetPadList(2);
98	    params.padBottom = src.GetPadList(3);
99	    params.channelSize = src.GetChannelSize() > 0 ? src.GetChannelSize() : params.fmapC1 * params.fmapC0;
100	    params.outH = (params.fmapH + params.padTop + params.padBottom - params.dilationH * (params.filterH - 1) - 1) /
101	                      params.strideH +
102	                  1;
103	    params.outW = (params.fmapW + params.padLeft + params.padRight - params.dilationW * (params.filterW - 1) - 1) /
104	                      params.strideW +
105	                  1;
106	
107	    return params;
108	}
109	
110	template <typename TileData, typename ConvTileData, SetFmatrixMode FmatrixMode = SetFmatrixMode::FMATRIX_A_MANUAL>
111	PTO_INTERNAL void TIMG2COL_IMPL(TileData& dst, ConvTileData& src, uint16_t posM, uint16_t posK)
112	{
113	    (void)FmatrixMode;
114	    cpu_img2col::Timg2colCheck<TileData, ConvTileData>();
115	
116	    const auto params = ExtractImg2ColParams(src);
117	    const int64_t mPerBatch = params.fmapD * params.outH * params.outW;
118	    const int64_t kernelSize = params.filterH * params.filterW;
119	    const int64_t kC0HW = params.fmapC0 * kernelSize;
120	    const auto padValue = src.GetPadValue();
121	
122	    for (int r = 0; r < dst.GetValidRow(); ++r) {
123	        const int64_t mIndex = static_cast<int64_t>(posM) + r;
124	        const int64_t nIndex = mIndex / mPerBatch;
125	        const int64_t remAfterN = mIndex % mPerBatch;
126	        const int64_t dIndex = remAfterN / (params.outH * params.outW);
127	        const int64_t remAfterD = remAfterN % (params.outH * params.outW);
128	        const int64_t outRow = remAfterD / params.outW;
129	        const int64_t outCol = remAfterD % params.outW;
130	
131	        for (int c = 0; c < dst.GetValidCol(); ++c) {
132	            const int64_t kIndex = static_cast<int64_t>(posK) + c;
133	            const int64_t c1Index = kIndex / kC0HW;
134	            const int64_t c0Index = kIndex % params.fmapC0;
135	            const int64_t kernelOffset = (kIndex % kC0HW) / (params.fmapC0);
136	            const int64_t kernelH = kernelOffset / params.filterW;
137	            const int64_t kernelW = kernelOffset % params.filterW;
138	
139	            auto value = CalculateValue(
140	                src, params, nIndex, dIndex, c1Index, c0Index, kernelH, kernelW, outRow, outCol, padValue);
141	
142	            dst.data()[GetTileElementOffset<TileData>(r, c)] = value;
143	        }
144	    }
145	}
146	
147	template <typename ConvTileData>
148	PTO_INTERNAL auto CalculateValue(
149	    const ConvTileData& src, const Img2ColParams<ConvTileData>& params, int64_t nIndex, int64_t dIndex, int64_t c1Index,
150	    int64_t c0Index, int64_t kernelH, int64_t kernelW, int64_t outRow, int64_t outCol,
151	    const typename ConvTileData::DType& padValue)
152	{
153	    auto value = padValue;
154	
155	    if (nIndex < params.fmapN && c1Index < params.fmapC1 && c0Index < params.fmapC0) {
156	        const int64_t inputH = outRow * params.strideH + kernelH * params.dilationH - params.padTop;
157	        const int64_t inputW = outCol * params.strideW + kernelW * params.dilationW - params.padLeft;
158	
159	        if (inputH >= 0 && inputH < params.fmapH && inputW >= 0 && inputW < params.fmapW) {
160	            const size_t srcOffset = cpu_img2col::GetInputOffset(src, nIndex, dIndex, c1Index, inputH, inputW, c0Index);
161	            value = src.data()[srcOffset];
162	        }
163	    }
164	
165	    return value;
166	}
167	
168	} // namespace pto
169	
170	#endif
