18	
19	template <typename T, typename U>
20	void conv2d_forward(
21	    uint32_t fmapN, uint32_t fmapC1, uint32_t fmapH, uint32_t fmapW, uint32_t fmapC0, uint32_t filterDim3,
22	    uint32_t filterDim2, uint32_t filterDim1, uint32_t filterDim0, uint32_t hk, uint32_t wk, uint8_t dilationH = 1,
23	    uint8_t dilationW = 1, uint8_t strideH = 1, uint8_t strideW = 1, uint8_t padTop = 1, uint8_t padBottom = 1,
24	    uint8_t padLeft = 1, uint8_t padRight = 1)
25	{
26	    uint32_t widthOut = 0;
27	    uint32_t heightOut = 0;
28	    if (strideH != 0 && strideW != 0) {
29	        heightOut = (fmapH + padTop + padBottom - dilationH * (hk - 1) - 1) / strideH + 1;
30	        widthOut = (fmapW + padLeft + padRight - dilationW * (wk - 1) - 1) / strideW + 1;
31	    }
32	    size_t aFileSize = fmapN * fmapC1 * fmapH * fmapW * fmapC0 * sizeof(U);
33	    size_t bFileSize = filterDim3 * filterDim2 * filterDim1 * filterDim0 * sizeof(U);
34	    size_t cFileSize = fmapN * heightOut * widthOut * filterDim2 * filterDim1 * sizeof(T);
35	
36	    aclInit(nullptr);
37	    aclrtSetDevice(0);
38	    aclrtStream stream;
39	    aclrtCreateStream(&stream);
40	
41	    uint8_t *dstHost, *src0Host, *src1Host;
42	    uint8_t *dstDevice, *src0Device, *src1Device;
43	
44	    aclrtMallocHost((void**)(&dstHost), cFileSize);
45	    aclrtMallocHost((void**)(&src0Host), aFileSize);
46	    aclrtMallocHost((void**)(&src1Host), bFileSize);
47	
48	    aclrtMalloc((void**)&dstDevice, cFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
49	    aclrtMalloc((void**)&src0Device, aFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
50	    aclrtMalloc((void**)&src1Device, bFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
51	
52	    ReadFile("../input/x1_gm.bin", aFileSize, src0Host, aFileSize);
53	    ReadFile("../input/x2_gm.bin", bFileSize, src1Host, bFileSize);
54	
55	    aclrtMemcpy(src0Device, aFileSize, src0Host, aFileSize, ACL_MEMCPY_HOST_TO_DEVICE);
56	    aclrtMemcpy(src1Device, bFileSize, src1Host, bFileSize, ACL_MEMCPY_HOST_TO_DEVICE);
57	    launchConv2dForward<U>(dstDevice, src0Device, src1Device, stream);
58	
59	    aclrtSynchronizeStream(stream);
60	    aclrtMemcpy(dstHost, cFileSize, dstDevice, cFileSize, ACL_MEMCPY_DEVICE_TO_HOST);
61	
62	    WriteFile("../output/output_z.bin", dstHost, cFileSize);
63	
64	    aclrtFree(dstDevice);
65	    aclrtFree(src0Device);
66	    aclrtFree(src1Device);
67	
68	    aclrtFreeHost(dstHost);
69	    aclrtFreeHost(src0Host);
70	    aclrtFreeHost(src1Host);
71	    aclrtDestroyStream(stream);
72	    aclrtResetDevice(0);
73	    aclFinalize();
74	
75	    std::vector<T> golden(cFileSize);
